// routes/export.ts
import { Request, Response } from 'express';
import { db } from '../db'; // Assuming db import path

// Helper function for CSV quoting
function csvQuote(value: any): string {
  if (typeof value !== 'string') {
    value = String(value);
  }
  // Escape quotes and wrap in quotes if value contains comma, newline, or quote
  if (value.includes(',') || value.includes('\n') || value.includes('"')) {
    return `"${value.replace(/"/g, '""')}"`;
  }
  return value;
}

export async function exportOrders(req: Request, res: Response) {
  const { status } = req.query;
  const { tenantId } = req.user;

  if (!tenantId || !status) {
    return res.status(400).send("Missing tenantId or status.");
  }

  res.setHeader("Content-Type", "text/csv");
  res.setHeader("Content-Disposition", `attachment; filename=orders_${Date.now()}.csv`);
  res.setHeader("Transfer-Encoding", "chunked"); // Ensure proper streaming

  // Write header row
  res.write("id,email,total\n");

  try {
    const iterator = db.order.iterate({ 
      where: { status }, 
      batchSize: 100, 
      // CRITICAL: Tenant scoping
      where: { ...db.order.where, tenantId: tenantId } 
    });

    for await (const order of iterator) {
      // Quote all fields
      const row = [
        csvQuote(order.id),
        csvQuote(order.email),
        csvQuote(order.total),
      ].join(',');
      res.write(row + '\n');
    }

    res.end();
  } catch (error) {
    console.error("Error during order export:", error);
    if (!res.headersSent) {
      res.status(500).send("Failed to generate export.");
    }
  }
}
