// routes/export.test.ts
import { Request, Response } from 'express';
import { exportOrders } from './export';
import { mockDb } from '../test/mockDb'; // Assume mock DB setup

describe('exportOrders', () => {
  it('should stream CSV data correctly and enforce tenant isolation', async () => {
    // Setup mock iterator returning 3 records, all belonging to tenant A
    mockDb.order.iterate.mockResolvedValue([
      { id: 1, email: 'a@t.com', total: 100, tenantId: 'tenantA' },
      { id: 2, email: 'b@t.com', total: 200, tenantId: 'tenantA' },
      // Test CSV complexity: comma, quote, newline
      { id: 3, email: 'c@t.com", "complex, cell\n', total: 300, tenantId: 'tenantA' }, 
    ]);

    // Mock response stream
    const mockRes = { 
      setHeader: jest.fn(), 
      write: jest.fn().mockReturnThis(), 
      end: jest.fn(), 
      status: jest.fn().mockReturnThis(),
      headersSent: false
    };

    const mockReq: Partial<Request> = { 
      query: { status: 'completed' }, 
      user: { tenantId: 'tenantA' } 
    };

    await exportOrders(mockReq as Request, mockRes as Response);

    // 1. Verify headers set for CSV/streaming
    expect(mockRes.setHeader).toHaveBeenCalledWith("Content-Type", "text/csv");
    expect(mockRes.setHeader).toHaveBeenCalledWith("Transfer-Encoding", "chunked");

    // 2. Verify data was written (Header + 3 rows)
    const expectedWrites = [
      "id,email,total\n", // Header
      "1,a@t.com,100\n",
      `2,b@t.com,200\n`,
      // Row 3 must be correctly quoted: "c@t.com","complex, cell\n"
      `3,"c@t.com","\"complex, cell\n\""\n` // Note: The internal quote must be doubled when CSV quoted
    ];

    expect(mockRes.write).toHaveBeenCalledTimes(4); // 1 header + 3 data rows
    // Check the complex row content structure (simplified check for implementation validity)
    expect(mockRes.write.mock.calls[3][0]).toContain(`3,"c@t.com",""complex, cell\n""`); 

    // 3. Verify stream termination
    expect(mockRes.end).toHaveBeenCalledTimes(1);
  });

  it('should return 400 if tenantId is missing', async () => {
    const mockRes = { setHeader: jest.fn(), status: jest.fn().mockReturnThis(), send: jest.fn() };
    const mockReq: Partial<Request> = { query: { status: 'completed' }, user: {} };

    await exportOrders(mockReq as Request, mockRes as Response);
    expect(mockRes.status).toHaveBeenCalledWith(400);
  });
});
